        // Admin dashboard: batches-per-year bar chart + track distribution pie chart.
        public async Task<DashboardChartsDTO> GetDashboardChartsAsync()
        {
            var batchesByYear = await _context.NFD_Batches
                .GroupBy(b => b.StartDate.Year)
                .Select(g => new ChartPointDTO { Label = g.Key.ToString(), Value = g.Count() })
                .OrderBy(p => p.Label)
                .ToListAsync();

            var tracksDistribution = await _context.NFD_Batches
                .Include(b => b.Program).ThenInclude(p => p.Track)
                .GroupBy(b => b.Program.Track.Name)
                .Select(g => new ChartPointDTO { Label = g.Key, Value = g.Count() })
                .ToListAsync();

            return new DashboardChartsDTO { BatchesByYear = batchesByYear, TracksDistribution = tracksDistribution };
        }



        // Retrieves database-backed metrics and lists for the Admin dashboard.
        public async Task<AdminDashboardSummaryDTO> GetAdminDashboardSummaryAsync()
        {
            var totalTrainees = await _context.NFD_Trainees.CountAsync();

            var activeTrainees = await _context.NFD_Trainees
                .CountAsync(t => t.Status == NFD_TraineeStatus.InTraining);

            var totalCompanies = await _context.NFD_Companies.CountAsync();
            var totalBatches = await _context.NFD_Batches.CountAsync();
            var totalCertificates = await _context.NFD_Certificates.CountAsync();

            var totalCapacity = await _context.NFD_Companies
                .SumAsync(c => (decimal?)c.Capacity) ?? 0m;

            var enrollments = await _context.NFD_Enrollments
                .AsNoTracking()
                .Include(e => e.Trainee)
                    .ThenInclude(t => t.User)
                .Include(e => e.Company)
                .Include(e => e.Batch)
                    .ThenInclude(b => b.Program)
                .Include(e => e.DailyAttendances)
                .ThenInclude(a => a.Excuses)
                       .Include(e => e.Evaluations)
                .ThenInclude(ev => ev.EvaluationTemplate)
                .ToListAsync();

            var activeEnrollments = enrollments
                .Where(e => e.CompletionStatus == NFD_EnrollmentCompletionStatus.InProgress)
                .ToList();

            var usedCapacity = activeEnrollments
                .Select(e => e.TraineeId)
                .Distinct()
                .Count();

            var allAttendance = enrollments
                .SelectMany(e => e.DailyAttendances)
                .ToList();

            var overallAttendanceRate = allAttendance.Count > 0
                ? Math.Round(
                    allAttendance.Count(a => a.Status == NFD_AttendanceStatus.Present)
                    * 100.0 / allAttendance.Count, 1)
                : 0.0;





            // ================================================
            // Dynamic Dashboard Evaluation - Per Batch
            // ================================================

            var batchIds = activeEnrollments
                .Select(e => e.BatchId)
                .Distinct()
                .ToList();

            var traineeIds = activeEnrollments
                .Select(e => e.TraineeId)
                .Distinct()
                .ToList();

            var enrollmentIds = activeEnrollments
                .Select(e => e.EnrollmentId)
                .ToList();

            // 1. Load batch tasks
            var batchTasks = await _context.NFD_Tasks
                .AsNoTracking()
                .Where(t => batchIds.Contains(t.BatchId))
                .ToListAsync();

            // 2. Load batch quizzes
            var batchQuizzes = await _context.NFD_Quizzes
                .AsNoTracking()
                .Where(q => batchIds.Contains(q.BatchId))
                .ToListAsync();

            // 3. Load projects assigned to batches
            var projectBatches = await _context.NFD_ProjectBatches
                .AsNoTracking()
                .Where(p => batchIds.Contains(p.BatchId))
                .ToListAsync();

            // 4. Load trainee submissions
            var submissions = await _context.NFD_Submissions
                .AsNoTracking()
                .Where(s => traineeIds.Contains(s.TraineeId))
                .ToListAsync();

            // 5. Load quiz attempts
            var quizAttempts = await _context.NFD_QuizAttempts
                .AsNoTracking()
                .Where(q => traineeIds.Contains(q.TraineeId))
                .ToListAsync();

            // 6. Load trainer project grades ONLY
            var projectGrades = await _context.NFD_TrainerProjectGrades
                .AsNoTracking()
                .Where(g => enrollmentIds.Contains(g.EnrollmentId))
                .ToListAsync();

            // ================================================
            // Calculate each trainee independently
            // ================================================

            var traineeStats = activeEnrollments.Select(enrollment =>
            {
                var batch = enrollment.Batch;

                // Attendance - approved excuses are excluded
                var attendanceRecords = enrollment.DailyAttendances
                    .Where(a => !a.Excuses.Any(x =>
                        x.Status == NFD_ExcuseStatus.Approved))
                    .ToList();

                int totalAttendance = attendanceRecords.Count;

                int presentDays = attendanceRecords.Count(a =>
                    a.Status == NFD_AttendanceStatus.Present);

                double attendance = totalAttendance > 0
                    ? Math.Round(presentDays * 100.0 / totalAttendance, 2)
                    : 0;

                // Tasks
                var tasks = batchTasks
                    .Where(t => t.BatchId == enrollment.BatchId)
                    .ToList();

                var taskScores = new List<double>();

                foreach (var task in tasks)
                {
                    var submission = submissions
                        .Where(s =>
                            s.TraineeId == enrollment.TraineeId &&
                            s.TaskId == task.TaskId &&
                            s.Status.ToString() == "Graded")
                        .OrderByDescending(s => s.SubmittedAt)
                        .FirstOrDefault();

                    if (submission == null ||
                        !double.TryParse(submission.Grade, out double grade))
                    {
                        continue;
                    }

                    taskScores.Add(grade);
                }

                bool tasksComplete = tasks.Count == taskScores.Count;

                double tasksPercentage = tasksComplete && tasks.Count > 0
                    ? taskScores.Average()
                    : 0;

                // Quizzes
                var quizzes = batchQuizzes
                    .Where(q => q.BatchId == enrollment.BatchId)
                    .ToList();

                var quizScores = new List<double>();

                foreach (var quiz in quizzes)
                {
                    var attempts = quizAttempts
                        .Where(a =>
                            a.TraineeId == enrollment.TraineeId &&
                            a.QuizId == quiz.QuizId &&
                            a.SubmittedAt != null)
                        .ToList();

                    if (attempts.Count > 0)
                        quizScores.Add((double)attempts.Max(a => a.Percentage));
                }

                bool quizzesComplete = quizzes.Count == quizScores.Count;

                double quizzesPercentage = quizzesComplete && quizzes.Count > 0
                    ? quizScores.Average()
                    : 0;

                // Projects - trainer grades only
                var projectIds = projectBatches
                    .Where(p => p.BatchId == enrollment.BatchId)
                    .Select(p => p.ProjectId)
                    .Distinct()
                    .ToList();

                var grades = projectGrades
                    .Where(g =>
                        g.EnrollmentId == enrollment.EnrollmentId &&
                        projectIds.Contains(g.ProjectId))
                    .GroupBy(g => g.ProjectId)
                    .Select(g => (double)g.OrderByDescending(x => x.GradedAt)
                                          .First().Score)
                    .ToList();

                bool projectsComplete = projectIds.Count == 0 ||
                                        grades.Count == projectIds.Count;

                double projectsPercentage = grades.Count > 0
                    ? grades.Average()
                    : 0;

                // Calculate only applicable weighted components
                double weightedScore = 0;
                double totalApplicableWeight = 0;

                bool attendanceComplete = totalAttendance > 0;

                if (batch.AttendanceWeight > 0 && attendanceComplete)
                {
                    weightedScore += attendance * (double)batch.AttendanceWeight;
                    totalApplicableWeight += (double)batch.AttendanceWeight;
                }

                if (batch.TasksWeight > 0 && tasks.Count > 0 && tasksComplete)
                {
                    weightedScore += tasksPercentage * (double)batch.TasksWeight;
                    totalApplicableWeight += (double)batch.TasksWeight;
                }

                if (batch.QuizzesWeight > 0 && quizzes.Count > 0 && quizzesComplete)
                {
                    weightedScore += quizzesPercentage * (double)batch.QuizzesWeight;
                    totalApplicableWeight += (double)batch.QuizzesWeight;
                }

                if (batch.ProjectsWeight > 0 && projectIds.Count > 0 && projectsComplete)
                {
                    weightedScore += projectsPercentage * (double)batch.ProjectsWeight;
                    totalApplicableWeight += (double)batch.ProjectsWeight;
                }

                // Do not classify incomplete evaluations
                bool isComplete =
                    (batch.AttendanceWeight <= 0 || attendanceComplete) &&
                    (batch.TasksWeight <= 0 || tasks.Count == 0 || tasksComplete) &&
                    (batch.QuizzesWeight <= 0 || quizzes.Count == 0 || quizzesComplete) &&
                    (batch.ProjectsWeight <= 0 || projectsComplete) &&
                    totalApplicableWeight > 0;

                double performance = isComplete
                    ? Math.Round(weightedScore / totalApplicableWeight, 2)
                    : 0;

                return new
                {
                    Enrollment = enrollment,
                    Performance = performance,
                    Attendance = attendance,
                    IsComplete = isComplete,

                    IsExcellent =
                        isComplete &&
                        performance >= (double)batch.ExcellentMinScore &&
                        attendance >= (double)batch.ExcellentMinAttendance,

                    IsVeryGood =
                        isComplete &&
                        performance >= (double)batch.VeryGoodMinScore &&
                        attendance >= (double)batch.VeryGoodMinAttendance,

                    IsAtRisk =
                        isComplete &&
                        (attendance < (double)batch.AtRiskMinAttendance ||
                         performance < (double)batch.GoodMinScore)
                };
            }).ToList();

            // ================================================
            // Top Performers
            // ================================================

            var topPerformers = traineeStats
                .Where(x => x.IsExcellent)
                .OrderByDescending(x => x.Performance)
                .ThenByDescending(x => x.Attendance)
                .Select(x => new AdminDashboardTraineeDTO
                {
                    TraineeId = x.Enrollment.TraineeId,
                    EnrollmentId = x.Enrollment.EnrollmentId,
                    FullName = x.Enrollment.Trainee.User?.FullName,
                    Major = x.Enrollment.Trainee.Major,
                    CompanyName = x.Enrollment.Company?.CompanyName,
                    GitHubUrl = x.Enrollment.Trainee.GitHubUrl,
                    LinkedInUrl = x.Enrollment.Trainee.LinkedInUrl,
                    PerformancePercent = x.Performance,
                    AttendancePercent = x.Attendance
                })
                .ToList();

            // ================================================
            // At Risk Trainees
            // ================================================

            var atRiskTrainees = traineeStats
                .Where(x => x.IsAtRisk)
                .OrderBy(x => x.Attendance)
                .ThenBy(x => x.Performance)
                .Select(x => new AdminDashboardTraineeDTO
                {
                    TraineeId = x.Enrollment.TraineeId,
                    EnrollmentId = x.Enrollment.EnrollmentId,
                    FullName = x.Enrollment.Trainee.User?.FullName,
                    Major = x.Enrollment.Trainee.Major,
                    CompanyName = x.Enrollment.Company?.CompanyName,
                    GitHubUrl = x.Enrollment.Trainee.GitHubUrl,
                    LinkedInUrl = x.Enrollment.Trainee.LinkedInUrl,
                    PerformancePercent = x.Performance,
                    AttendancePercent = x.Attendance
                })
                .ToList();

            var attendanceWeeks = allAttendance
                .GroupBy(a => (
                    Year: System.Globalization.ISOWeek.GetYear(a.Date),
                    Week: System.Globalization.ISOWeek.GetWeekOfYear(a.Date)))
                .OrderByDescending(g => g.Key.Year)
                .ThenByDescending(g => g.Key.Week)
                .Take(6)
                .OrderBy(g => g.Key.Year)
                .ThenBy(g => g.Key.Week)
                .Select(g => new ChartPointDTO
                {
                    Label = $"أسبوع {g.Key.Week}",
                    Value = Math.Round(
                        g.Count(a => a.Status == NFD_AttendanceStatus.Present)
                        * 100.0 / g.Count(), 1)
                })
                .ToList();

            var companyDistribution = activeEnrollments
                .GroupBy(e => e.Company?.CompanyName ?? "غير محدد")
                .Select(g => new ChartPointDTO
                {
                    Label = g.Key,
                    Value = g.Count()
                })
                .OrderByDescending(x => x.Value)
                .ToList();

            var programDistribution = activeEnrollments
                .GroupBy(e => e.Batch?.Program?.Title ?? "غير محدد")
                .Select(g => new ChartPointDTO
                {
                    Label = g.Key,
                    Value = g.Count()
                })
                .OrderByDescending(x => x.Value)
                .ToList();

            var warnings = await _context.NFD_Warnings
                .AsNoTracking()
                .Include(w => w.Company)
                .Include(w => w.Enrollment)
                .ThenInclude(e => e!.Trainee)
                .ThenInclude(t => t.User)
                .OrderByDescending(w => w.IssuedDate)
                .ThenByDescending(w => w.WarningId)
                .Take(6)
                .ToListAsync();

            var recentWarnings = warnings
                .Select(w => new AdminDashboardWarningDTO
                {
                    WarningId = w.WarningId,
                    Scope = w.Scope.ToString(),
                    TraineeId = w.Enrollment?.TraineeId,
                    CompanyId = w.CompanyId,
                    TargetName = w.Scope == NFD_WarningScope.Company
                        ? w.Company?.CompanyName
                        : w.Enrollment?.Trainee?.User?.FullName,
                    GitHubUrl = w.Enrollment?.Trainee?.GitHubUrl,
                    LinkedInUrl = w.Enrollment?.Trainee?.LinkedInUrl,
                    Type = w.Type.ToString(),
                    Level = w.Level.ToString(),
                    Status = w.Status.ToString(),
                    IssuedDate = w.IssuedDate
                })
                .ToList();

            var averageTopScore = topPerformers.Count > 0
                ? Math.Round(topPerformers.Average(t => t.PerformancePercent), 1)
                : 0.0;

            return new AdminDashboardSummaryDTO
            {
                TotalTrainees = totalTrainees,
                ActiveTrainees = activeTrainees,
                TotalCompanies = totalCompanies,
                TotalBatches = totalBatches,
                TotalCertificates = totalCertificates,
                OverallAttendanceRate = overallAttendanceRate,
                TopPerformersCount = topPerformers.Count,
                TopPerformersAvgScore = averageTopScore,
                AtRiskCount = atRiskTrainees.Count,

                Capacity = new CompanyCapacityDTO
                {
                    Total = totalCapacity,
                    Used = usedCapacity,
                    Remaining = totalCapacity - usedCapacity
                },

                AttendanceWeeks = attendanceWeeks,
                CompanyDistribution = companyDistribution,
                ProgramDistribution = programDistribution,
                TopPerformers = topPerformers,
                AtRiskTrainees = atRiskTrainees,
                RecentWarnings = recentWarnings
            };
        }


        // Admin Reports: end-of-batch performance drill-down.
        public async Task<BatchPerformanceReportDTO?> GetBatchPerformanceAsync(
            int batchId, int pageNumber, int pageSize)
        {
            if (pageNumber < 1) pageNumber = 1;
            if (pageSize < 1) pageSize = 15;

            var batch = await _context.NFD_Batches
                .Include(b => b.Program)
                .FirstOrDefaultAsync(b => b.BatchId == batchId);

            if (batch == null) return null;

            var totalCount = await _context.NFD_Enrollments
                .CountAsync(e => e.BatchId == batchId);

            if (totalCount == 0)
            {
                return new BatchPerformanceReportDTO
                {
                    BatchId = batch.BatchId,
                    BatchName = batch.BatchName,
                    ProgramName = batch.Program?.Title,
                    CompanyName = null,
                    AvgAttendance = 0,
                    SuccessRate = 0,
                    Rows = new List<BatchPerformanceRowDTO>(),
                    TotalCount = 0,
                    PageNumber = pageNumber,
                    PageSize = pageSize
                };
            }

            // ==========================================================
            // 1) إحصائيات الدفعة الكاملة (لازم تشمل كل المتدربين حتى تكون
            //    متوسط الحضور ونسبة النجاح صحيحة) — بدون تحميل بيانات
            //    User/Company الثقيلة، فقط الحضور والتقييمات.
            // ==========================================================
            var allEnrollmentsLean = await _context.NFD_Enrollments
                .Where(e => e.BatchId == batchId)
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations).ThenInclude(ev => ev.EvaluationTemplate)
                .OrderBy(e => e.TraineeId)
                .ToListAsync();

            static decimal AvgFor(NFD_Enrollment enrollment, NFD_EvaluationType type)
            {
                var scores = enrollment.Evaluations
                    .Where(e => e.EvaluationTemplate != null && e.EvaluationTemplate.Type == type)
                    .Select(e => e.Score)
                    .ToList();
                return scores.Count > 0 ? scores.Average() : 0m;
            }

            static double AttendanceRateFor(NFD_Enrollment enrollment)
            {
                var total = enrollment.DailyAttendances.Count;
                var present = enrollment.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Present);
                return total > 0 ? (double)present / total * 100.0 : 0.0;
            }

            static string LevelFor(decimal overallAvg) => overallAvg switch
            {
                >= 90 => "ممتاز",
                >= 80 => "جيد جداً",
                >= 70 => "جيد",
                >= 60 => "مقبول",
                _ => "راسب"
            };

            var allStats = allEnrollmentsLean.Select(e =>
            {
                var technical = AvgFor(e, NFD_EvaluationType.Technical);
                var behavioral = AvgFor(e, NFD_EvaluationType.Behavioral);
                var final = AvgFor(e, NFD_EvaluationType.Final);
                var overall = new[] { technical, behavioral, final }.Where(s => s > 0).ToList();
                var overallAvg = overall.Count > 0 ? overall.Average() : 0m;

                return new
                {
                    e.EnrollmentId,
                    e.TraineeId,
                    AttendanceRate = AttendanceRateFor(e),
                    Technical = Math.Round(technical, 1),
                    Behavioral = Math.Round(behavioral, 1),
                    Final = Math.Round(final, 1),
                    Level = LevelFor(overallAvg)
                };
            }).ToList();

            var avgAttendance = Math.Round(allStats.Average(s => s.AttendanceRate), 1);
            var successRate = Math.Round(allStats.Count(s => s.Level != "راسب") * 100.0 / allStats.Count, 1);

            // ==========================================================
            // 2) تحديد صفوف الصفحة الحالية فقط
            // ==========================================================
            var pageEnrollmentIds = allStats
                .Select(s => s.EnrollmentId)
                .Skip((pageNumber - 1) * pageSize)
                .Take(pageSize)
                .ToList();

            // بيانات الاسم/التخصص/الشركة تُحمّل فقط لصفوف الصفحة الحالية
            var pageEnrollments = await _context.NFD_Enrollments
                .Where(e => pageEnrollmentIds.Contains(e.EnrollmentId))
                .Include(e => e.Trainee).ThenInclude(t => t.User)
                .Include(e => e.Company)
                .ToDictionaryAsync(e => e.EnrollmentId);

            var companyName = pageEnrollments.Values.Select(e => e.Company?.CompanyName).FirstOrDefault();
            if (companyName == null)
            {
                // يحصل فقط إذا طُلبت صفحة تتجاوز عدد الصفحات المتاحة
                var anyEnrollmentId = allStats.Select(s => s.EnrollmentId).FirstOrDefault();
                companyName = await _context.NFD_Enrollments
                    .Where(e => e.EnrollmentId == anyEnrollmentId)
                    .Select(e => e.Company != null ? e.Company.CompanyName : null)
                    .FirstOrDefaultAsync();
            }

            var rows = pageEnrollmentIds
                .Select(id =>
                {
                    var stat = allStats.First(s => s.EnrollmentId == id);
                    var enrollment = pageEnrollments[id];

                    return new BatchPerformanceRowDTO
                    {
                        TraineeId = stat.TraineeId,
                        TraineeName = enrollment.Trainee?.User?.FullName,
                        Major = enrollment.Trainee?.Major,
                        AttendanceRate = Math.Round(stat.AttendanceRate, 1),
                        TechnicalScore = stat.Technical,
                        BehavioralScore = stat.Behavioral,
                        FinalScore = stat.Final,
                        Level = stat.Level
                    };
                }).ToList();

            return new BatchPerformanceReportDTO
            {
                BatchId = batch.BatchId,
                BatchName = batch.BatchName,
                ProgramName = batch.Program?.Title,
                CompanyName = companyName,
                AvgAttendance = avgAttendance,
                SuccessRate = successRate,
                Rows = rows,
                TotalCount = totalCount,
                PageNumber = pageNumber,
                PageSize = pageSize
            };
        }

        // Admin Reports - Company-specific Batch Performance
        public async Task<AdminCompanyBatchPerformanceDTO?>
            GetAdminCompanyBatchPerformanceAsync(
                int companyId,
                int batchId,
                int pageNumber,
                int pageSize)
        {
            if (pageNumber < 1) pageNumber = 1;
            if (pageSize < 1) pageSize = 15;

            var batch = await _context.NFD_Batches
                .AsNoTracking()
                .Include(b => b.Program)
                .FirstOrDefaultAsync(b => b.BatchId == batchId);

            if (batch == null) return null;

            var companyName = await _context.NFD_Companies
                .Where(c => c.CompanyId == companyId)
                .Select(c => c.CompanyName)
                .FirstOrDefaultAsync();

            if (companyName == null) return null;

            // Only enrollments belonging to this company and batch
            var enrollments = await _context.NFD_Enrollments
                .AsNoTracking()
                .Where(e =>
                    e.CompanyId == companyId &&
                    e.BatchId == batchId)
                .Include(e => e.Trainee)
                    .ThenInclude(t => t.User)
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations)
                    .ThenInclude(ev => ev.EvaluationTemplate)
                .OrderBy(e => e.TraineeId)
                .ToListAsync();

            static decimal? AverageScore(
                NFD_Enrollment enrollment,
                NFD_EvaluationType type)
            {
                var scores = enrollment.Evaluations
                    .Where(ev =>
                        ev.EvaluationTemplate != null &&
                        ev.EvaluationTemplate.Type == type)
                    .Select(ev => ev.Score)
                    .ToList();

                return scores.Count > 0 ? scores.Average() : null;
            }

            static double? AttendanceRate(NFD_Enrollment enrollment)
            {
                var total = enrollment.DailyAttendances.Count;

                if (total == 0) return null;

                var present = enrollment.DailyAttendances.Count(a =>
                    a.Status == NFD_AttendanceStatus.Present);

                return Math.Round((double)present / total * 100, 1);
            }

            static string GetLevel(decimal? score)
            {
                if (!score.HasValue) return "غير متوفر";

                return score.Value switch
                {
                    >= 90 => "ممتاز",
                    >= 80 => "جيد جداً",
                    >= 70 => "جيد",
                    >= 60 => "مقبول",
                    _ => "راسب"
                };
            }

            var stats = enrollments.Select(e =>
            {
                var technical = AverageScore(e, NFD_EvaluationType.Technical);
                var behavioral = AverageScore(e, NFD_EvaluationType.Behavioral);
                var final = AverageScore(e, NFD_EvaluationType.Final);

                var availableScores = new[]
                {
            technical,
            behavioral,
            final
        }
                .Where(x => x.HasValue)
                .Select(x => x!.Value)
                .ToList();

                decimal? overall = availableScores.Count > 0
                    ? availableScores.Average()
                    : null;

                return new
                {
                    Enrollment = e,
                    Attendance = AttendanceRate(e),
                    Technical = technical,
                    Behavioral = behavioral,
                    Final = final,
                    Level = GetLevel(overall)
                };
            }).ToList();

            var validAttendance = stats
                .Where(s => s.Attendance.HasValue)
                .Select(s => s.Attendance!.Value)
                .ToList();

            double? avgAttendance = validAttendance.Count > 0
    ? Math.Round(validAttendance.Average(), 1)
    : null;
            var assessed = stats
                .Where(s => s.Level != "غير متوفر")
                .ToList();

            double? successRate = assessed.Count > 0
                ? Math.Round(
                    assessed.Count(s => s.Level != "راسب")
                    * 100.0 / assessed.Count, 1)
                : null;

            var rows = stats
    .Skip((pageNumber - 1) * pageSize)
    .Take(pageSize)
    .Select(s => new AdminCompanyBatchPerformanceRowDTO
    {
        TraineeId = s.Enrollment.TraineeId,
        TraineeName = s.Enrollment.Trainee?.User?.FullName,
        Major = s.Enrollment.Trainee?.Major,
        AttendanceRate = s.Attendance,
        TechnicalScore = s.Technical.HasValue
            ? Math.Round(s.Technical.Value, 1) : null,
        BehavioralScore = s.Behavioral.HasValue
            ? Math.Round(s.Behavioral.Value, 1) : null,
        FinalScore = s.Final.HasValue
            ? Math.Round(s.Final.Value, 1) : null,
        Level = s.Level
    })
    .ToList();

            return new AdminCompanyBatchPerformanceDTO
            {
                BatchId = batch.BatchId,
                BatchName = batch.BatchName,
                ProgramName = batch.Program?.Title,
                CompanyName = companyName,
                AvgAttendance = avgAttendance,
                SuccessRate = successRate,
                Rows = rows,
                TotalCount = stats.Count,
                PageNumber = pageNumber,
                PageSize = pageSize
            };
        }

        // Company portal Reports: company-wide attendance report (spans batches).
        public async Task<AttendanceReportDTO?> GetCompanyAttendanceReportAsync(int companyId)
        {
            var enrollments = await _context.NFD_Enrollments
                .Include(e => e.Trainee).ThenInclude(t => t.User)
                .Include(e => e.DailyAttendances)
                .Where(e => e.CompanyId == companyId)
                .ToListAsync();

            if (enrollments.Count == 0) return null;

            var rows = enrollments.Select(e =>
            {
                var present = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Present);
                var late = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Late);
                var absent = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Absent);
                var excused = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Excused);
                var total = e.DailyAttendances.Count;

                return new AttendanceReportRowDTO
                {
                    TraineeId = e.TraineeId,
                    TraineeName = e.Trainee?.User?.FullName,
                    PresentDays = present,
                    LateDays = late,
                    AbsentDays = absent,
                    ExcusedDays = excused,
                    AttendanceRate = total > 0 ? Math.Round((double)present / total * 100.0, 1) : 0
                };
            }).ToList();

            return new AttendanceReportDTO
            {
                BatchId = null,
                BatchName = null,
                PeriodStart = enrollments.SelectMany(e => e.DailyAttendances).Select(a => (DateTime?)a.Date).Min(),
                PeriodEnd = enrollments.SelectMany(e => e.DailyAttendances).Select(a => (DateTime?)a.Date).Max(),
                OverallAttendanceRate = rows.Count > 0 ? Math.Round(rows.Average(r => r.AttendanceRate), 1) : 0,
                Rows = rows
            };
        }

        // Company portal Dashboard: weekly attendance chart (last 6 weeks).
        public async Task<List<ChartPointDTO>> GetCompanyAttendanceChartAsync(int companyId)
        {
            var records = await _context.NFD_DailyAttendances
                .Where(a => a.Enrollment.CompanyId == companyId)
                .ToListAsync();

            var byWeek = records
                .GroupBy(a => System.Globalization.ISOWeek.GetWeekOfYear(a.Date))
                .OrderByDescending(g => g.Key)
                .Take(6)
                .OrderBy(g => g.Key)
                .Select(g => new ChartPointDTO
                {
                    Label = $"أسبوع {g.Key}",
                    Value = Math.Round(g.Count(a => a.Status == NFD_AttendanceStatus.Present) * 100.0 / g.Count(), 1)
                })
                .ToList();

            return byWeek;
        }

        // Company portal Dashboard: trainee distribution by program.
        public async Task<List<ChartPointDTO>> GetCompanyProgramDistributionAsync(int companyId)
        {
            return await _context.NFD_Enrollments
                .Include(e => e.Batch).ThenInclude(b => b.Program)
                .Where(e => e.CompanyId == companyId)
                .GroupBy(e => e.Batch.Program.Title)
                .Select(g => new ChartPointDTO { Label = g.Key, Value = g.Count() })
                .ToListAsync();
        }

        // Company portal Dashboard: top performers, ranked by average evaluation score.
        public async Task<List<int>> GetCompanyTopPerformerTraineeIdsAsync(int companyId, int take)
        {
            var ranked = await _context.NFD_Enrollments
                .Where(e => e.CompanyId == companyId)
                .Select(e => new
                {
                    e.TraineeId,
                    AvgScore = e.Evaluations.Count() > 0 ? e.Evaluations.Average(ev => ev.Score) : 0
                })
                .OrderByDescending(x => x.AvgScore)
                .Take(take)
                .ToListAsync();

            return ranked.Select(x => x.TraineeId).ToList();
        }

        // Company portal Dashboard: at-risk trainees (low attendance or low scores).
        public async Task<List<int>> GetCompanyAtRiskTraineeIdsAsync(int companyId, int take)
        {
            const double attendanceThreshold = 80.0;
            const decimal scoreThreshold = 60m;

            var enrollments = await _context.NFD_Enrollments
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations)
                .Where(e => e.CompanyId == companyId)
                .ToListAsync();

            var atRisk = enrollments
                .Select(e =>
                {
                    var total = e.DailyAttendances.Count;
                    var present = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Present);
                    var attendanceRate = total > 0 ? (double)present / total * 100.0 : 100.0;
                    var avgScore = e.Evaluations.Count > 0 ? e.Evaluations.Average(ev => ev.Score) : 100m;

                    return new { e.TraineeId, attendanceRate, avgScore };
                })
                .Where(x => x.attendanceRate < attendanceThreshold || x.avgScore < scoreThreshold)
                .OrderBy(x => x.attendanceRate)
                .Take(take)
                .Select(x => x.TraineeId)
                .ToList();

            return atRisk;
        }

        // Trainer Reports: attendance rate / task completion rate / avg technical
        // grade across every batch this trainer is assigned to.
        public async Task<TrainerKpisDTO> GetTrainerKpisAsync(int trainerId)
        {
            var batchIds = await _context.NFD_BatchTrainers
                .Where(bt => bt.TrainerId == trainerId)
                .Select(bt => bt.BatchId)
                .ToListAsync();

            var enrollments = await _context.NFD_Enrollments
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations).ThenInclude(ev => ev.EvaluationTemplate)
                .Where(e => batchIds.Contains(e.BatchId))
                .ToListAsync();

            var totalDays = enrollments.SelectMany(e => e.DailyAttendances).Count();
            var presentDays = enrollments.SelectMany(e => e.DailyAttendances).Count(a => a.Status == NFD_AttendanceStatus.Present);
            var attendanceRate = totalDays > 0 ? (double)presentDays / totalDays * 100.0 : (double?)null;

            var tasksForBatches = await _context.NFD_Tasks
                .Where(t => batchIds.Contains(t.BatchId))
                .Select(t => t.TaskId)
                .ToListAsync();
            var submissions = await _context.NFD_Submissions
                .Where(s => tasksForBatches.Contains(s.TaskId))
                .ToListAsync();
            var taskCompletionRate = submissions.Count > 0
                ? submissions.Count(s => s.Status == NFD_SubmissionStatus.Graded) * 100.0 / submissions.Count
                : (double?)null;

            var technicalScores = enrollments
                .SelectMany(e => e.Evaluations)
                .Where(ev => ev.EvaluationTemplate != null && ev.EvaluationTemplate.Type == NFD_EvaluationType.Technical)
                .Select(ev => ev.Score)
                .ToList();
            var avgTechnicalGrade = technicalScores.Count > 0 ? (double)technicalScores.Average() : (double?)null;

            return new TrainerKpisDTO
            {
                AttendanceRate = (double)(attendanceRate.HasValue
    ? Math.Round(attendanceRate.Value, 1)
    : (double?)null),
                TaskCompletionRate = (double)(taskCompletionRate.HasValue
    ? Math.Round(taskCompletionRate.Value, 1)
    : (double?)null),
                AvgTechnicalGrade = (double)(avgTechnicalGrade.HasValue ? Math.Round(avgTechnicalGrade.Value, 1) : (double?)null)
            };
        }

        //==========================================================
        // Admin Reports: end-of-batch performance drill-down (paginated).


        // ==========================================================
        // Trainer Trainees Report
        // ==========================================================
        public async Task<List<TrainerTraineesReportRowDto>>
            GetTrainerTraineesReportRowsAsync(
                int trainerId,
                int? batchId,
                int? traineeId
            )
        {
            // Get batches assigned to this trainer
            var trainerBatchIds =
                await _context.NFD_BatchTrainers
                    .Where(bt =>
                        bt.TrainerId == trainerId
                    )
                    .Select(bt =>
                        bt.BatchId
                    )
                    .ToListAsync();


            // If a specific batch was requested,
            // make sure it belongs to this trainer.
            if (batchId.HasValue)
            {
                if (!trainerBatchIds.Contains(batchId.Value))
                {
                    return new List<TrainerTraineesReportRowDto>();
                }

                trainerBatchIds =
                    new List<int>
                    {
                batchId.Value
                    };
            }


            var enrollments =
                await _context.NFD_Enrollments

                    .Include(e =>
                        e.Trainee
                    )
                    .ThenInclude(t =>
                        t.User
                    )

                    .Include(e =>
                        e.Batch
                    )

                    .Include(e =>
                        e.DailyAttendances
                    )

                    .Include(e =>
                        e.Evaluations
                    )

                   .Where(e =>
    trainerBatchIds.Contains(e.BatchId) &&
    (!traineeId.HasValue || e.TraineeId == traineeId.Value)
)

                    .ToListAsync();


            var rows =
                enrollments
                    .Select(e =>
                    {
                        // ------------------------------------------
                        // Attendance
                        // ------------------------------------------

                        var totalDays =
                            e.DailyAttendances.Count;

                        var presentDays =
                            e.DailyAttendances.Count(
                                a =>
                                    a.Status ==
                                    NFD_AttendanceStatus.Present
                            );


                        var attendancePercentage =
                            totalDays > 0
                                ? Math.Round(
                                    (double)presentDays /
                                    totalDays *
                                    100.0,
                                    1
                                )
                                : 0.0;


                        // ------------------------------------------
                        // Evaluation Average
                        // ------------------------------------------

                        var averageScore =
                            e.Evaluations.Count > 0
                                ? Math.Round(
                                    e.Evaluations.Average(
                                        ev => ev.Score
                                    ),
                                    1
                                )
                                : 0m;


                        // ------------------------------------------
                        // Technical Level
                        // Same thresholds used in trainer frontend
                        // ------------------------------------------

                        var technicalLevel =
                            averageScore switch
                            {
                                >= 85 => "ممتاز",
                                >= 70 => "جيد",
                                >= 60 => "متوسط",
                                _ => "يحتاج تطوير"
                            };


                        return new TrainerTraineesReportRowDto
                        {
                            EnrollmentId =
                                e.EnrollmentId,

                            TraineeId =
                                e.TraineeId,

                            TraineeName =
                                e.Trainee?.User?.FullName,

                            BatchId =
                                e.BatchId,

                            BatchName =
                                e.Batch?.BatchName,

                            AttendancePercentage =
                                attendancePercentage,

                            AverageScore =
                                averageScore,

                            TechnicalLevel =
                                technicalLevel
                        };
                    })
                    .ToList();


            return rows;
        }
        // ==========================================================
        // Admin Reports - Companies Summary
        // ==========================================================
        public async Task<AdminCompaniesSummaryDTO> GetAdminCompaniesSummaryAsync()
        {
            var companies = await _context.NFD_Companies
                .AsNoTracking()
                .Select(c => new AdminCompanyReportItemDTO
                {
                    CompanyId = c.CompanyId,
                    CompanyName = c.CompanyName,
                    CommercialRegister = c.CommercialRegister,
                    WorkField = c.WorkField,
                    Address = c.Address,
                    Phone = c.Phone,
                    Email = c.Email,
                    Capacity = c.Capacity,
                    Status = c.Status.ToString(),

                    TraineesCount = _context.NFD_Enrollments
        .Where(e => e.CompanyId == c.CompanyId)
        .Select(e => e.TraineeId)
        .Distinct()
        .Count(),

                    ProgramsCount = _context.NFD_CompanyPrograms
        .Count(cp => cp.CompanyId == c.CompanyId),

                    BatchesCount = _context.NFD_Enrollments
        .Where(e => e.CompanyId == c.CompanyId)
        .Select(e => e.BatchId)
        .Distinct()
        .Count()
                })
                .ToListAsync();

            // Get company-specific enrollments with real batch and program data
            var enrollmentRows = await (
                from e in _context.NFD_Enrollments.AsNoTracking()
                join b in _context.NFD_Batches.AsNoTracking()
                    on e.BatchId equals b.BatchId
                join p in _context.NFD_Programs.AsNoTracking()
                    on b.ProgramId equals p.ProgramId
                join t in _context.NFD_Tracks.AsNoTracking()
                    on p.TrackId equals t.TrackId
                where e.CompanyId != null
                select new
                {
                    e.CompanyId,
                    e.TraineeId,
                    b.BatchId,
                    b.BatchName,
                    b.StartDate,
                    b.EndDate,
                    p.ProgramId,
                    ProgramName = p.Title,
                    TrackName = t.Name
                }
            ).ToListAsync();

            // Group by company, then program, then batch
            foreach (var company in companies)
            {
                var companyRows = enrollmentRows
                    .Where(x => x.CompanyId == company.CompanyId)
                    .ToList();

                company.Programs = companyRows
                    .GroupBy(x => new
                    {
                        x.ProgramId,
                        x.ProgramName,
                        x.TrackName
                    })
                    .Select(programGroup => new AdminCompanyProgramDTO
                    {
                        ProgramId = programGroup.Key.ProgramId,
                        ProgramName = programGroup.Key.ProgramName,
                        TrackName = programGroup.Key.TrackName,

                        BatchesCount = programGroup
                            .Select(x => x.BatchId)
                            .Distinct()
                            .Count(),

                        TraineesCount = programGroup
                            .Select(x => x.TraineeId)
                            .Distinct()
                            .Count(),

                        Batches = programGroup
                            .GroupBy(x => new
                            {
                                x.BatchId,
                                x.BatchName,
                                x.StartDate,
                                x.EndDate
                            })
                            .Select(batchGroup => new AdminCompanyBatchDTO
                            {
                                BatchId = batchGroup.Key.BatchId,
                                BatchName = batchGroup.Key.BatchName,
                                StartDate = batchGroup.Key.StartDate,
                                EndDate = batchGroup.Key.EndDate,

                                TraineesCount = batchGroup
                                    .Select(x => x.TraineeId)
                                    .Distinct()
                                    .Count()
                            })
                            .OrderBy(x => x.BatchId)
                            .ToList()
                    })
                    .OrderBy(x => x.ProgramId)
                    .ToList();
            }

            return new AdminCompaniesSummaryDTO
            {
                TotalCompanies = companies.Count,
                TotalHostedTrainees = companies.Sum(c => c.TraineesCount),
                Companies = companies
            };
        }
    }
